/*
 * OpenRISC OR1K System-on-Chip for ISAComp Linux Platform
 *
 * Integrates:
 *   - OR1K CPU core (generated by ISAComp)
 *   - Memory (64MB unified)
 *   - UART (NS16550A compatible)
 *   - Programmable Interrupt Controller (OR1K PIC)
 *   - Tick Timer (built into CPU via SPRs)
 *
 * Memory Map:
 *   0x00000000 - 0x03FFFFFF  RAM (64MB)
 *   0x90000000 - 0x900000FF  PIC registers
 *   0x90000100 - 0x900001FF  UART registers
 */

module or1k_soc #(
    parameter MEM_SIZE = 64*1024*1024,  // 64MB
    parameter UART_BASE = 32'h90000100,
    parameter PIC_BASE  = 32'h90000000
)(
    input  wire        clk,
    input  wire        rst_n,
    // UART
    input  wire        uart_rx,
    output wire        uart_tx,
    // External interrupts
    input  wire [31:0] ext_irq
);

    // CPU memory interface
    wire [31:0] imem_addr;
    wire [31:0] imem_rdata;
    wire [31:0] dmem_addr;
    wire [31:0] dmem_rdata;
    wire [31:0] dmem_wdata;
    wire        dmem_we;
    wire [3:0]  dmem_be;

    // Interrupt signals
    wire        irq_pending;
    wire        tick_irq_pending;  // From tick timer to CPU

    // Address decode
    wire is_ram    = (dmem_addr < MEM_SIZE);
    wire is_uart   = (dmem_addr >= UART_BASE) && (dmem_addr < UART_BASE + 256);
    wire is_pic    = (dmem_addr >= PIC_BASE) && (dmem_addr < PIC_BASE + 256);

    // =========================================================================
    // Memory
    // =========================================================================
    reg [31:0] mem [0:MEM_SIZE/4-1];

    // Instruction fetch (read-only)
    assign imem_rdata = mem[imem_addr[25:2]];

    // Data access
    wire [31:0] ram_rdata = mem[dmem_addr[25:2]];

    always @(posedge clk) begin
        if (dmem_we && is_ram) begin
            if (dmem_be[0]) mem[dmem_addr[25:2]][7:0]   <= dmem_wdata[7:0];
            if (dmem_be[1]) mem[dmem_addr[25:2]][15:8]  <= dmem_wdata[15:8];
            if (dmem_be[2]) mem[dmem_addr[25:2]][23:16] <= dmem_wdata[23:16];
            if (dmem_be[3]) mem[dmem_addr[25:2]][31:24] <= dmem_wdata[31:24];
        end
    end

    // =========================================================================
    // UART (NS16550A compatible - simplified)
    // =========================================================================
    reg [7:0] uart_tx_data;
    reg       uart_tx_valid;
    reg [7:0] uart_rx_data;
    reg       uart_rx_valid;
    reg [7:0] uart_ier;        // Interrupt Enable Register
    reg [7:0] uart_iir;        // Interrupt Identification Register
    reg [7:0] uart_lcr;        // Line Control Register
    reg [7:0] uart_mcr;        // Modem Control Register
    reg [7:0] uart_lsr;        // Line Status Register
    reg [7:0] uart_msr;        // Modem Status Register
    reg [7:0] uart_scr;        // Scratch Register
    reg [15:0] uart_dll;       // Divisor Latch

    wire uart_tx_ready = 1'b1;  // Always ready in simulation
    assign uart_tx = 1'b1;      // Idle high

    // LSR: bit 0 = data ready, bit 5 = TX holding reg empty, bit 6 = TX empty
    wire [7:0] uart_lsr_val = {1'b0, uart_tx_ready, uart_tx_ready, 4'b0, uart_rx_valid};

    wire [31:0] uart_rdata;
    wire [2:0] uart_reg_sel = dmem_addr[4:2];

    assign uart_rdata = (uart_reg_sel == 3'd0) ? {24'b0, uart_rx_data} :     // RBR/THR
                        (uart_reg_sel == 3'd1) ? {24'b0, uart_ier} :          // IER
                        (uart_reg_sel == 3'd2) ? {24'b0, uart_iir} :          // IIR
                        (uart_reg_sel == 3'd3) ? {24'b0, uart_lcr} :          // LCR
                        (uart_reg_sel == 3'd4) ? {24'b0, uart_mcr} :          // MCR
                        (uart_reg_sel == 3'd5) ? {24'b0, uart_lsr_val} :      // LSR
                        (uart_reg_sel == 3'd6) ? {24'b0, uart_msr} :          // MSR
                        {24'b0, uart_scr};                                    // SCR

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            uart_tx_valid <= 0;
            uart_rx_valid <= 0;
            uart_ier <= 0;
            uart_lcr <= 0;
            uart_mcr <= 0;
            uart_scr <= 0;
        end else begin
            uart_tx_valid <= 0;
            if (dmem_we && is_uart) begin
                case (uart_reg_sel)
                    3'd0: begin  // THR - Transmit
                        uart_tx_data <= dmem_wdata[7:0];
                        uart_tx_valid <= 1;
                        // Print to simulation console
                        $write("%c", dmem_wdata[7:0]);
                    end
                    3'd1: uart_ier <= dmem_wdata[7:0];
                    3'd3: uart_lcr <= dmem_wdata[7:0];
                    3'd4: uart_mcr <= dmem_wdata[7:0];
                    3'd7: uart_scr <= dmem_wdata[7:0];
                endcase
            end
        end
    end

    // =========================================================================
    // PIC (OR1K Programmable Interrupt Controller)
    // =========================================================================
    reg [31:0] pic_mr;     // PIC Mask Register (which IRQs are enabled)
    reg [31:0] pic_sr;     // PIC Status Register (which IRQs are pending)

    wire [31:0] pic_rdata;
    wire pic_reg_sel = dmem_addr[2];

    assign pic_rdata = pic_reg_sel ? {24'b0, pic_sr[7:0]} : {24'b0, pic_mr[7:0]};

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pic_mr <= 0;
            pic_sr <= 0;
        end else begin
            // Update pending status from external IRQs
            pic_sr <= ext_irq & pic_mr;

            if (dmem_we && is_pic) begin
                if (!pic_reg_sel)
                    pic_mr <= dmem_wdata;
                else
                    pic_sr <= pic_sr & ~dmem_wdata;  // Write 1 to clear
            end
        end
    end

    // IRQ pending signal to CPU
    assign irq_pending = |pic_sr;

    // =========================================================================
    // Tick Timer (OR1K Programmable Tick Timer)
    // =========================================================================
    // The tick timer is architecturally part of the CPU (SPR group 10),
    // but implemented as a SoC-level module that generates tick_irq_pending.
    // The CPU accesses TTMR/TTCR via memory-mapped I/O at the timer base.
    //
    // TTMR (Mode Register):
    //   [31:30] TP - Timer Mode: 00=disabled, 01=restart, 10=one-shot, 11=continuous
    //   [29]    IP - Interrupt Pending
    //   [27:0]  TP - Timer Period (match value)
    //
    // TTCR (Count Register):
    //   [27:0]  count value

    localparam TIMER_BASE = 32'h90000200;
    wire is_timer = (dmem_addr >= TIMER_BASE) && (dmem_addr < TIMER_BASE + 256);

    reg [31:0] ttmr;           // Tick Timer Mode Register
    reg [31:0] ttcr;           // Tick Timer Count Register
    wire [1:0]  timer_mode  = ttmr[31:30];
    wire [27:0] timer_period = ttmr[27:0];
    wire [27:0] timer_count  = ttcr[27:0];
    wire        timer_enabled = (timer_mode != 2'b00);
    wire        timer_match   = timer_enabled && (timer_count == timer_period);

    wire [31:0] timer_rdata = dmem_addr[2] ? ttcr : ttmr;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ttmr <= 0;
            ttcr <= 0;
        end else begin
            // Counter update
            if (timer_enabled) begin
                if (timer_match) begin
                    case (timer_mode)
                        2'b01: ttcr[27:0] <= 28'b0;       // Restart mode
                        2'b10: /* stop */;                  // One-shot mode
                        2'b11: ttcr[27:0] <= timer_count + 1; // Continuous
                    endcase
                    ttmr[29] <= 1'b1;  // Set IP (interrupt pending) on match
                end else begin
                    ttcr[27:0] <= timer_count + 1;
                end
            end

            // CPU writes via memory-mapped I/O
            if (dmem_we && is_timer) begin
                if (!dmem_addr[2])
                    ttmr <= dmem_wdata;
                else
                    ttcr <= dmem_wdata;
            end
        end
    end

    // Tick timer interrupt: pending when IP bit is set
    assign tick_irq_pending = ttmr[29];

    // =========================================================================
    // Data read mux
    // =========================================================================
    assign dmem_rdata = is_uart  ? uart_rdata :
                        is_pic   ? pic_rdata :
                        is_timer ? timer_rdata :
                        ram_rdata;

    // =========================================================================
    // CPU Core (instantiate generated processor)
    // =========================================================================
    // The generated processor module will be instantiated here
    // or1k_mmu cpu (
    //     .clk(clk),
    //     .rst_n(rst_n),
    //     .imem_addr(imem_addr),
    //     .imem_rdata(imem_rdata),
    //     .dmem_addr(dmem_addr),
    //     .dmem_rdata(dmem_rdata),
    //     .dmem_wdata(dmem_wdata),
    //     .dmem_we(dmem_we),
    //     .irq_pending(irq_pending),
    //     .tick_irq_pending(tick_irq_pending)
    // );

    // =========================================================================
    // Memory initialization (for simulation)
    // =========================================================================
    initial begin
        $readmemh("firmware.hex", mem);
    end

    // Simulation timeout
    initial begin
        #100000000;
        $display("TIMEOUT");
        $finish;
    end

endmodule
